<?php get_header(); $term=get_queried_object(); $title=is_tax()?single_term_title('',false):'所有店家'; $desc=is_tax()?term_description($term):'探索 BSKTV 收錄的商務 KTV 與酒店店家。'; $current_tax=is_tax()?$term->taxonomy:''; $current_slug=is_tax()?$term->slug:''; $cities=get_terms(array('taxonomy'=>'bsktv_city','hide_empty'=>true,'number'=>12)); $types=get_terms(array('taxonomy'=>'bsktv_type','hide_empty'=>true,'number'=>12)); ?>
<main class="container section"><header class="archive-head"><span class="eyebrow">BSKTV DIRECTORY</span><h1><?php echo esc_html($title); ?></h1><?php if($desc)echo '<div class="archive-desc">'.wp_kses_post($desc).'</div>'; ?></header>
<div class="filter-bar"><form action="<?php echo esc_url(home_url('/')); ?>" method="get" role="search"><label class="screen-reader-text" for="bsktv-directory-search">搜尋店家</label><input id="bsktv-directory-search" type="search" name="s" placeholder="搜尋店家名稱、關鍵字…" value="<?php echo esc_attr(get_search_query()); ?>"><input type="hidden" name="post_type" value="post"><button class="btn btn-primary" type="submit">搜尋</button></form></div>
<div class="directory-filters" aria-label="店家分類篩選"><div class="filter-group"><strong>城市</strong><div class="filter-links"><a class="<?php echo $current_tax===''?'is-active':''; ?>" href="<?php echo esc_url(get_post_type_archive_link('post')?:home_url('/')); ?>">全部</a><?php if(!is_wp_error($cities))foreach($cities as $city){$url=get_term_link($city);if(!is_wp_error($url))echo '<a class="'.($current_tax==='bsktv_city'&&$current_slug===$city->slug?'is-active':'').'" href="'.esc_url($url).'">'.esc_html($city->name).'</a>';} ?></div></div><div class="filter-group"><strong>類型</strong><div class="filter-links"><a class="<?php echo $current_tax===''?'is-active':''; ?>" href="<?php echo esc_url(get_post_type_archive_link('post')?:home_url('/')); ?>">全部</a><?php if(!is_wp_error($types))foreach($types as $type){$url=get_term_link($type);if(!is_wp_error($url))echo '<a class="'.($current_tax==='bsktv_type'&&$current_slug===$type->slug?'is-active':'').'" href="'.esc_url($url).'">'.esc_html($type->name).'</a>';} ?></div></div></div>
<?php if(have_posts()): ?><div class="directory-toolbar"><span>共 <?php echo esc_html($wp_query->found_posts); ?> 間店家</span><span>依最近更新排序</span></div><div class="store-grid"><?php while(have_posts()):the_post();get_template_part('template-parts/store-card');endwhile; ?></div><div class="pagination"><?php the_posts_pagination(array('mid_size'=>1,'prev_text'=>'← 上一頁','next_text'=>'下一頁 →','screen_reader_text'=>'店家分頁')); ?></div><?php else: ?><div class="empty-state"><h2>目前沒有符合條件的店家</h2><p>換個關鍵字、城市或店家類型再試試。</p><a class="btn btn-primary" href="<?php echo esc_url(home_url('/')); ?>">回到首頁</a></div><?php endif; ?></main><?php get_footer(); ?>
